from copy import deepcopy


def order_entries(entries, policy):
    if policy not in {"low", "high", "keep"}:
        raise ValueError("invalid policy")
    if not isinstance(entries, list) or any(
        not isinstance(item, dict)
        or "rank" not in item
        or not isinstance(item["rank"], int)
        or isinstance(item["rank"], bool)
        for item in entries
    ):
        raise ValueError("invalid entries")
    copied = deepcopy(entries)
    if policy == "keep":
        return entries
    return sorted(copied, key=lambda item: item["rank"], reverse=policy == "high")

